-- Applied before you got here. It is what ./db.sh reseed recreates.
CREATE TABLE orders (
    id             bigint      PRIMARY KEY,
    placed_at      timestamptz NOT NULL,
    total_cents    integer     NOT NULL,
    shipped_at     timestamptz,
    cancelled_at   timestamptz,
    refunded_cents integer     NOT NULL DEFAULT 0
);

CREATE INDEX orders_placed_at_idx ON orders (placed_at);

tool_args.content:
-- Add orders.status with batched backfill, no long locks, no table rewrite.

SET lock_timeout = '500ms';
SET statement_timeout = '700ms';

ALTER TABLE orders ADD COLUMN status text;

-- Batched backfill via a procedure that commits between batches.
CREATE OR REPLACE PROCEDURE backfill_orders_status()
LANGUAGE plpgsql AS $$
DECLARE
    batch_size CONSTANT int := 5000;
    min_id     bigint;
    max_id     bigint;
    lo         bigint;
    hi         bigint;
BEGIN
    SELECT MIN(id), MAX(id) INTO min_id, max_id FROM orders;
    IF min_id IS NULL THEN
        RETURN;
    END IF;

    lo := min_id;
    WHILE lo <= max_id LOOP
        hi := lo + batch_size - 1;
        UPDATE orders
           SET status = CASE
                            WHEN cancelled_at IS NOT NULL THEN 'cancelled'
                            WHEN refunded_cents > 0 AND refunded_cents >= total_cents THEN 'refunded'
                            WHEN refunded_cents > 0 THEN 'partly_refunded'
                            WHEN shipped_at IS NOT NULL THEN 'shipped'
                            ELSE 'placed'
                        END
         WHERE id >= lo AND id <= hi;
        COMMIT;
        lo := hi + 1;
    END LOOP;
END;
$$;

CALL backfill_orders_status();

DROP PROCEDURE backfill_orders_status();

-- Add CHECK constraint NOT VALID (catalogue write only, no table scan)
ALTER TABLE orders ADD CONSTRAINT orders_status_check
    CHECK (status IN ('cancelled','refunded','partly_refunded','shipped','placed'))
    NOT VALID;

-- Validate the constraint (scan under SHARE UPDATE EXCLUSIVE, no read/write block)
ALTER TABLE orders VALIDATE CONSTRAINT orders_status_check;

-- SET NOT NULL is now a catalogue change (validated constraint proves the column)
ALTER TABLE orders ALTER COLUMN status SET NOT NULL;

-- Remove orders.status, leaving the table exactly as 0001 built it.

